"""Synthesis Quality Gate: verifies coverage, citations, contradictions, and actionability."""

from __future__ import annotations

import re
from typing import Any, List, Optional
from pydantic import BaseModel, Field

from app.db.models import EvidenceClaim
from app.schemas.project import ResearchPlan
from app.schemas.synthesis import ConsultingSynthesis


class QACheckResult(BaseModel):
    """Evaluation report generated by the Synthesis Quality Gate."""
    passed: bool = Field(..., description="Whether the synthesis meets the minimum release threshold")
    overall_score: float = Field(..., ge=0.0, le=1.0, description="Overall synthesis quality score (0.0 - 1.0)")
    question_coverage_score: float = Field(..., ge=0.0, le=1.0)
    citation_completeness_score: float = Field(..., ge=0.0, le=1.0)
    actionability_score: float = Field(..., ge=0.0, le=1.0)
    unaddressed_questions: List[str] = Field(default_factory=list)
    uncited_finding_ids: List[str] = Field(default_factory=list)
    contradictions_detected: List[str] = Field(default_factory=list)
    duplicate_findings: List[str] = Field(default_factory=list)
    issues: List[str] = Field(default_factory=list)


def _tokenize(text: str) -> set[str]:
    """Extract lowercased alphanumeric words for token similarity."""
    return set(re.findall(r"\b[a-zA-Z0-9]{3,}\b", text.lower()))


class SynthesisQualityGate:
    """Rigorous QA gate evaluating synthesis completeness and grounding before human review."""

    def __init__(
        self,
        min_citation_threshold: float = 0.80,
        min_question_coverage_threshold: float = 0.70,
        min_actionability_threshold: float = 0.75,
    ) -> None:
        self.min_citation_threshold = min_citation_threshold
        self.min_question_coverage_threshold = min_question_coverage_threshold
        self.min_actionability_threshold = min_actionability_threshold

    def evaluate(
        self,
        synthesis: ConsultingSynthesis,
        plan: Optional[ResearchPlan] = None,
        evidence_claims: Optional[List[EvidenceClaim]] = None,
    ) -> QACheckResult:
        """Run all quality gate checks on the candidate synthesis."""
        issues: list[str] = []

        # ------------------------------------------------------------------
        # 1. Citation Completeness Check
        # ------------------------------------------------------------------
        total_findings = len(synthesis.findings)
        uncited_finding_ids: list[str] = []

        if total_findings > 0:
            for f in synthesis.findings:
                if not f.evidence_ids:
                    uncited_finding_ids.append(f.id)
            cited_count = total_findings - len(uncited_finding_ids)
            citation_completeness = cited_count / total_findings
        else:
            citation_completeness = 0.0
            issues.append("Synthesis contains 0 findings.")

        if citation_completeness < self.min_citation_threshold:
            issues.append(
                f"Citation completeness ({citation_completeness:.1%}) below required threshold ({self.min_citation_threshold:.1%})."
            )

        # ------------------------------------------------------------------
        # 2. Research Question Coverage Check
        # ------------------------------------------------------------------
        unaddressed_questions: list[str] = []
        if plan and plan.questions:
            all_synthesis_text = " ".join([
                synthesis.executive_summary,
                " ".join(f.finding for f in synthesis.findings),
                " ".join(g.gap_description for g in synthesis.gaps),
            ])
            synthesis_tokens = _tokenize(all_synthesis_text)

            for q in plan.questions:
                q_tokens = _tokenize(q)
                if not q_tokens:
                    continue
                # Overlap ratio between question tokens and synthesis content
                overlap = len(q_tokens.intersection(synthesis_tokens)) / len(q_tokens)
                if overlap < 0.35:
                    unaddressed_questions.append(q)

            question_coverage = 1.0 - (len(unaddressed_questions) / len(plan.questions))
        else:
            question_coverage = 1.0

        if question_coverage < self.min_question_coverage_threshold:
            issues.append(
                f"Research question coverage ({question_coverage:.1%}) below required threshold ({self.min_question_coverage_threshold:.1%})."
            )

        # ------------------------------------------------------------------
        # 3. Contradiction Detection
        # ------------------------------------------------------------------
        contradictions_detected: list[str] = []
        if evidence_claims:
            for c in evidence_claims:
                if c.is_contradiction:
                    contradictions_detected.append(
                        f"Unresolved contradiction in evidence: {c.claim_text[:120]}..."
                    )

        # Also inspect risks for explicit contradiction mentions
        for rk in synthesis.risks:
            if "contradict" in rk.risk.lower() or "conflicting" in rk.risk.lower():
                contradictions_detected.append(f"Risk highlights conflicting data: {rk.risk}")

        if contradictions_detected:
            issues.append(f"Detected {len(contradictions_detected)} unresolved contradiction(s).")

        # ------------------------------------------------------------------
        # 4. Actionability Check on Recommendations
        # ------------------------------------------------------------------
        total_recs = len(synthesis.recommendations)
        actionable_count = 0
        if total_recs > 0:
            for r in synthesis.recommendations:
                has_action = len(r.action.strip()) >= 15
                has_timeframe = bool(r.timeframe and len(r.timeframe.strip()) >= 3)
                has_priority = bool(r.priority in {"high", "medium", "low"})
                if has_action and has_timeframe and has_priority:
                    actionable_count += 1
            actionability = actionable_count / total_recs
        else:
            actionability = 0.0
            issues.append("Synthesis contains 0 recommendations.")

        if actionability < self.min_actionability_threshold:
            issues.append(
                f"Recommendation actionability ({actionability:.1%}) below required threshold ({self.min_actionability_threshold:.1%})."
            )

        # ------------------------------------------------------------------
        # 5. Duplicate Finding Detection
        # ------------------------------------------------------------------
        duplicate_findings: list[str] = []
        for i in range(len(synthesis.findings)):
            for j in range(i + 1, len(synthesis.findings)):
                f1 = synthesis.findings[i]
                f2 = synthesis.findings[j]
                t1 = _tokenize(f1.finding)
                t2 = _tokenize(f2.finding)
                if t1 and t2:
                    jaccard = len(t1.intersection(t2)) / len(t1.union(t2))
                    if jaccard > 0.70:
                        duplicate_findings.append(f"Duplicate finding detected: {f1.id} and {f2.id}")
                        issues.append(f"Redundant findings: {f1.id} and {f2.id} share >70% vocabulary.")

        # ------------------------------------------------------------------
        # Compute Overall Score & Decision
        # ------------------------------------------------------------------
        overall_score = (
            (citation_completeness * 0.40)
            + (question_coverage * 0.35)
            + (actionability * 0.25)
        )
        passed = (
            citation_completeness >= self.min_citation_threshold
            and question_coverage >= self.min_question_coverage_threshold
            and actionability >= self.min_actionability_threshold
            and len(duplicate_findings) == 0
        )

        return QACheckResult(
            passed=passed,
            overall_score=round(overall_score, 2),
            question_coverage_score=round(question_coverage, 2),
            citation_completeness_score=round(citation_completeness, 2),
            actionability_score=round(actionability, 2),
            unaddressed_questions=unaddressed_questions,
            uncited_finding_ids=uncited_finding_ids,
            contradictions_detected=contradictions_detected,
            duplicate_findings=duplicate_findings,
            issues=issues,
        )
